-- Preflight administrativo de solo lectura. Sin datos comerciales ni credenciales.
begin isolation level read committed read only;
set local search_path='';
select statement_timestamp() captura,
(select to_jsonb(c)-'actualizado_en' from crm.piloto_f8_control c where singleton) control,
(select jsonb_agg(to_jsonb(m)-'actualizado_en' order by perfil_id) from crm.piloto_f8_miembros m where activo) miembros,
(select jsonb_object_agg(nombre,activo) from crm.multiempresa_flags) banderas,
(select jsonb_agg(jsonb_build_object('perfil_id',p.id,'rol_portal',p.rol,'rol_crm',e.rol_crm,'supervisor_id',e.supervisor_id,
'auth_vigente',u.id is not null and u.deleted_at is null and u.email_confirmed_at is not null
and (u.banned_until is null or u.banned_until<=statement_timestamp())
and exists(select 1 from auth.identities ai where ai.user_id=p.id and ai.provider='email')) order by p.id)
from crm.equipo e join public.perfiles p on p.id=e.perfil_id left join auth.users u on u.id=p.id where e.activo and p.activo) equipo,
(select coalesce(jsonb_agg(p.id order by p.id),'[]') from public.perfiles p
where private.rol_crm(p.id)='directorio' or (p.activo and p.rol='directorio' and not exists(select 1 from crm.equipo e where e.perfil_id=p.id))) lectores_globales,
(select jsonb_agg(jsonb_build_object('firma',p.oid::regprocedure::text,'huella',md5(pg_get_functiondef(p.oid)),'propietario',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text collate "C")
